mapper.select:
SELECT catalog_product_id
FROM loan_product_catalog
WHERE source_type = #{sourceType}
  AND source_product_key = #{sourceProductKey}
  AND source_product_subtype = COALESCE(#{sourceProductSubtype}, '')
LIMIT 1

SELECT catalog_product_id AS catalogProductId, source_product_key AS sourceProductKey, product_name AS productName, loan_type AS loanType, min_rate AS minRate, max_rate AS maxRate, max_limit_amount AS maxLimitAmount, max_period_months AS maxPeriodMonths, target_description AS targetDescription, active, institution_name AS institutionName, join_way AS joinWay, disclosure_start_date AS disclosureStartDate, disclosure_end_date AS disclosureEndDate, collected_at AS collectedAt, updated_at AS updatedAt FROM loan_product_catalog
loan_type = #{loanType}
AND active = #{active}
ORDER BY loan_type, institution_name, product_name, catalog_product_id
